figure.sourcecode:
ReadVarint(data):
  // 可変長整数の長さは、最初のバイトの
  // 先頭2ビットにエンコードされています。
  v = data.next_byte()
  prefix = v >> 6
  length = 1 << prefix

  // 長さがわかったら、これらのビットを取り除き、
  // 残りのバイトを読み取ります。
  v = v & 0x3f
  repeat length-1 times:
    v = (v << 8) + data.next_byte()
  return v

EncodePacketNumber(full_pn, largest_acked):

  // ビット数は、新しいパケットを含む、連続した
  // 未確認応答のパケット番号の数の2を底とする対数より、
  // 少なくとも1大きくなければなりません。
  if largest_acked is None:
    num_unacked = full_pn + 1
  else:
    num_unacked = full_pn - largest_acked

  min_bits = log(num_unacked, 2) + 1
  num_bytes = ceil(min_bits / 8)

  // 整数値をエンコードし、
  // 下位num_bytesバイトに切り詰めます。
  return encode(full_pn, num_bytes)

DecodePacketNumber(largest_pn, truncated_pn, pn_nbits):
   expected_pn  = largest_pn + 1
   pn_win       = 1 << pn_nbits
   pn_hwin      = pn_win / 2
   pn_mask      = pn_win - 1
   // 受信したパケット番号は、expected_pn - pn_hwin
   // より大きく、expected_pn + pn_hwin 以下である
   // はずです。
   //
   // つまり、expected_pn の末尾のビットを取り除いて
   // truncated_pn を加えるだけではいけません。そうすると
   // ウィンドウの外の値になる可能性があるためです。
   //
   // 次のコードは候補値を計算し、それがパケット番号の
   // ウィンドウ内にあることを確認します。
   // オーバーフローとアンダーフローを防ぐための追加の
   // チェックに注意してください。
   candidate_pn = (expected_pn & ~pn_mask) | truncated_pn
   if candidate_pn <= expected_pn - pn_hwin and
      candidate_pn < (1 << 62) - pn_win:
      return candidate_pn + pn_win
   if candidate_pn > expected_pn + pn_hwin and
      candidate_pn >= pn_win:
      return candidate_pn - pn_win
   return candidate_pn
